BEGIN TRANSACTION;
CREATE TABLE bookmarks (
	id INTEGER NOT NULL, 
	item_id INTEGER NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_bookmarks_item_id UNIQUE (item_id), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
INSERT INTO "bookmarks" VALUES(1,2,'2026-10-28 22:02:30.804713');
CREATE TABLE carryover_items (
	id INTEGER NOT NULL, 
	item_id INTEGER NOT NULL, 
	pinned_digest_id VARCHAR, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_carryover_item_id UNIQUE (item_id), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
CREATE TABLE digest_audits (
	id INTEGER NOT NULL, 
	digest_id VARCHAR NOT NULL, 
	audit_type VARCHAR NOT NULL, 
	payload_json TEXT NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(digest_id) REFERENCES digests (id) ON DELETE CASCADE
);
CREATE TABLE digest_item_features (
	id INTEGER NOT NULL, 
	digest_id VARCHAR NOT NULL, 
	item_id INTEGER NOT NULL, 
	item_label VARCHAR, 
	final_score FLOAT, 
	features_json TEXT NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_digest_item_features UNIQUE (digest_id, item_id), 
	FOREIGN KEY(digest_id) REFERENCES digests (id) ON DELETE CASCADE, 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
CREATE TABLE digest_items (
	id INTEGER NOT NULL, 
	digest_id VARCHAR NOT NULL, 
	item_id INTEGER NOT NULL, 
	item_label VARCHAR NOT NULL, 
	score FLOAT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_digest_items_item UNIQUE (digest_id, item_id), 
	CONSTRAINT uq_digest_items_label UNIQUE (digest_id, item_label), 
	FOREIGN KEY(digest_id) REFERENCES digests (id) ON DELETE CASCADE, 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
