CREATE TABLE digests (
	id VARCHAR NOT NULL, 
	created_at DATETIME, 
	item_count INTEGER, 
	sent_at DATETIME, 
	PRIMARY KEY (id)
);
INSERT INTO "digests" VALUES('2026-10-20','2026-10-28 22:02:30.131102',4,NULL);
CREATE TABLE email_digest_items (
	run_id VARCHAR NOT NULL, 
	item_label VARCHAR NOT NULL, 
	digest_id VARCHAR NOT NULL, 
	item_id INTEGER NOT NULL, 
	sent_at DATETIME NOT NULL, 
	PRIMARY KEY (run_id, item_label), 
	FOREIGN KEY(digest_id) REFERENCES digests (id) ON DELETE CASCADE, 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
CREATE TABLE feedback_events (
	id INTEGER NOT NULL, 
	item_id INTEGER NOT NULL, 
	value INTEGER NOT NULL, 
	grade INTEGER, 
	recorded_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_feedback_event_value CHECK (value IN (-1, 0, 1)), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
INSERT INTO "feedback_events" VALUES(1,1,1,2,'2026-10-28 22:02:30.154301');
CREATE TABLE impressions (
	id INTEGER NOT NULL, 
	run_id VARCHAR NOT NULL, 
	digest_id VARCHAR NOT NULL, 
	item_id INTEGER NOT NULL, 
	section VARCHAR NOT NULL, 
	position INTEGER NOT NULL, 
	final_score FLOAT, 
	model_version VARCHAR, 
	selected BOOLEAN NOT NULL, 
	viewed BOOLEAN NOT NULL, 
	primary_facet VARCHAR, 
	primary_facet_score FLOAT, 
	topic_score FLOAT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(digest_id) REFERENCES digests (id) ON DELETE CASCADE, 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
CREATE TABLE item_embeddings (
	id INTEGER NOT NULL, 
	item_id INTEGER NOT NULL, 
	model VARCHAR NOT NULL, 
	text_hash VARCHAR NOT NULL, 
	dim INTEGER NOT NULL, 
	vector BLOB NOT NULL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_item_embedding_item_model UNIQUE (item_id, model), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
