CREATE TABLE item_enrichment (
	item_id INTEGER NOT NULL, 
	cited_by_count INTEGER, 
	venue_impact FLOAT, 
	venue VARCHAR, 
	fetched_at DATETIME, 
	PRIMARY KEY (item_id), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
CREATE TABLE items (
	id INTEGER NOT NULL, 
	source VARCHAR NOT NULL, 
	section VARCHAR NOT NULL, 
	external_id VARCHAR NOT NULL, 
	url VARCHAR NOT NULL, 
	title TEXT NOT NULL, 
	abstract TEXT, 
	authors TEXT, 
	published_at DATETIME, 
	fetched_at DATETIME, 
	summary TEXT, 
	summary_signature VARCHAR, 
	summary_backend VARCHAR, 
	score FLOAT, 
	digest_id VARCHAR, 
	item_label VARCHAR, 
	metadata_json TEXT NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_source_external UNIQUE (source, external_id)
);
