CREATE TABLE known_items (
	id INTEGER NOT NULL, 
	item_id INTEGER NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_known_items_item_id UNIQUE (item_id), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
