CREATE TABLE opportunity_snapshots (
	id INTEGER NOT NULL, 
	item_id INTEGER NOT NULL, 
	details_hash VARCHAR NOT NULL, 
	details_json TEXT NOT NULL, 
	observed_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_opportunity_snapshot UNIQUE (item_id, details_hash), 
