	CONSTRAINT uq_votes_item_id UNIQUE (item_id), 
	CONSTRAINT ck_vote_value CHECK (value IN (-1, 0, 1)), 
	FOREIGN KEY(item_id) REFERENCES items (id) ON DELETE CASCADE
);
